function withLock<T>(fn: () => Promise<T>): Promise<T> {
  const run = chain.then(fn);
  chain = run.catch(() => undefined);
  return run;
}
async function increment() {
  await withLock(async () => {
    const current = count;
    await Promise.resolve();
